formulas.d20_check_resolution:
function resolveD20Check(opts) {
  const first = d(20), second = opts.advantage || opts.disadvantage ? d(20) : first, kept = opts.advantage && !opts.disadvantage ? Math.max(first, second) : opts.disadvantage && !opts.advantage ? Math.min(first, second) : first, lines = [...opts.extra ?? []];
  if (opts.abilityMod !== 0)
    lines.push({ label: "Ability", value: opts.abilityMod, source: "ability" });
  if (opts.bonus && opts.bonus !== 0)
    lines.push({ label: "Bonus", value: opts.bonus, source: "proficiency" });
  const flat = lines.reduce((a, l) => a + l.value, 0), total = kept + flat, nat20 = kept === 20, nat1 = kept === 1;
  let outcome;
  if (opts.autoFail)
    outcome = "critical-failure";
  else if (opts.system === "pf2e")
    outcome = pf2eOutcome(total, opts.dc, kept);
  else if (nat20)
    outcome = "critical-success";
  else if (nat1)
    outcome = "critical-failure";
  else
    outcome = total >= opts.dc ? "success" : "failure";
  const breakdown = `${opts.advantage || opts.disadvantage ? `d20(${first})${opts.disadvantage ? " \u21E3" : " \u21E1"} d20(${second}) \u2192 keep ${kept}` : `d20(${kept})`} + ${lines.map((l) => `${l.label} ${formatMod(l.value)}`).join(" + ") || "0"} = ${total} vs DC ${opts.dc} \u2192 ${outcome.replace("-", " ").toUpperCase()}`;
  return {
    rolls: opts.advantage || opts.disadvantage ? [first, second] : [first],
    kept,
    modifiers: lines,
    total,
    nat20,
    nat1,
    outcome,
    breakdown
  };
}

formulas.proficiency_bonus_for_level:
function profBonusForLevel(level) {
  return level <= 4 ? 2 : level <= 8 ? 3 : level <= 12 ? 4 : level <= 16 ? 5 : 6;
}

formulas.spell_slots_for_class:
function spellSlotsFor(klass, level) {
  if (klass.casterType === "pact") {
    const [count, slotLevel] = PACT_SLOTS[Math.min(level, 20) - 1];
    return { slots: [], pact: { count, slotLevel } };
  }
  if (klass.casterType === "full")
    return { slots: FULL_CASTER_SLOTS[Math.min(level, 20) - 1], pact: null };
  if (klass.casterType === "half")
    return { slots: HALF_CASTER_SLOTS[Math.min(level, 20) - 1], pact: null };
  return { slots: [], pact: null };
}

formulas.race_total_asi:
function raceTotalAsi(raceId, subraceId) {
  const race = RACE_MAP[raceId], effective = subraceOf(raceId, subraceId);
  if (effective?.variantHuman)
    return {};
  const out = { ...race.asi };
  for (const [k, v] of Object.entries(effective?.asi ?? {}))
    out[k] = (out[k] ?? 0) + v;
  return out;
}
